import pandas as pd, json, base64

result = {}
for name, path in [('olmo', 'results/exp002_olmo/exp002_olmo_arc.jsonl'), ('yi', 'results/exp002_yi/exp002_yi_arc.jsonl')]:
    df = pd.read_json('/root/nlp_variance_gtheory/' + path, lines=True)
    df = df.sort_values(['temperature','prompt_template','seed','ordering','item_id']).reset_index(drop=True)
    correct = df['correct'].values.tolist()
    while len(correct) % 8 != 0:
        correct.append(0)
    byte_arr = bytearray()
    for i in range(0, len(correct), 8):
        b = 0
        for j in range(8):
            b = (b << 1) | correct[i+j]
        byte_arr.append(b)
    b64 = base64.b64encode(bytes(byte_arr)).decode()
    result[name] = {'model_raw': df['model'].iloc[0], 'b64': b64, 'n': len(df)}

print(json.dumps(result))
"

